// n8n Code node — "Build COE Emails" (Run Once for All Items)
// Fired by Simple HRIS once per Certificate of Engagement request an employee
// files from Profile → Request Documents (POST /api/employee/documents). Fans
// out ONE item per recipient, each carrying a ready-to-send HTML email saying a
// COE is waiting in Accounting → Documents.
//
// WHO is mailed comes from the payload: the HRIS resolves it from Admin →
// Webhooks → "COE Request → Notify" → Open automation (default
// jakec@simple.biz). Subject and body are FIXED here — the caller only says who
// asked and when, so this endpoint cannot become an arbitrary-content mailer.
//
// NO PAY FIGURES: the HRIS never sends the rate or the certificate. Do not add
// them here either — the recipient list is admin-editable.
//
// Payload (n8n may nest the POST body under `.body`):
//   {
//     event: 'coe.requested', trigger: 'employee_coe_request',
//     request: { id, document_type: 'coe', document_label, employee_name,
//                employee_email, requested_at, requested_at_manila, note },
//     recipients: [ { email, name } ],
//     sent_by: 'system',
//     test: true            // Admin → Webhooks test run (goes to the admin only)
//   }

// --- OPTIONAL shared-secret gate ---
// Leave '' to accept any caller. To lock down: put a long random string here AND
// set HRIS env N8N_COE_REQUEST_NOTIFY_SECRET to the same value (sent as the
// 'x-webhook-secret' header).
const REQUIRED_SECRET = '';

const HRIS_LINK = 'https://simple-hris.vercel.app/';
const LOGO = 'https://simple-hris.vercel.app/simple-logo.png';
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const MAX = 300;

const root = (items[0] && items[0].json) || {};
const body = (root && typeof root.body === 'object' && root.body) ? root.body : root;
const headers = (root && typeof root.headers === 'object' && root.headers) ? root.headers : {};

const providedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || body.secret || '';
if (REQUIRED_SECRET && providedSecret !== REQUIRED_SECRET) {
  throw new Error('Unauthorized: missing or invalid webhook secret.');
}

if (body.event !== 'coe.requested') {
  throw new Error('Not a COE request event (got ' + JSON.stringify(body.event) + ').');
}

function esc(v) {
  if (v == null) return '';
  return String(v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// --- recipients (from the HRIS; validated, deduped, capped) ---
const seen = {};
const recipients = [];
for (const r of (Array.isArray(body.recipients) ? body.recipients : [])) {
  const email = String((r && r.email) || '').trim().toLowerCase();
  if (!EMAIL_RE.test(email) || seen[email]) continue;
  seen[email] = true;
  recipients.push(email);
}
if (recipients.length === 0) throw new Error('No valid recipients in the payload.');
if (recipients.length > MAX) throw new Error('Too many recipients (' + recipients.length + ' > ' + MAX + ').');

// --- the request ---
const req = (body.request && typeof body.request === 'object') ? body.request : {};
const isTest = body.test === true;
const name = esc(String(req.employee_name || '').trim()) || esc(req.employee_email) || 'An employee';
const workEmail = esc(req.employee_email || '');
const when = esc(req.requested_at_manila || req.requested_at || '');
const note = esc(String(req.note || '').trim());
const refId = esc(req.id || '');

const SUBJECT = (isTest ? '[TEST RUN] ' : '') + '📄 COE request — ' + (String(req.employee_name || '').trim() || 'an employee') + ' is waiting for a signature';

function detailRow(label, value) {
  if (!value) return '';
  return '<tr>' +
    '<td style="padding:8px 14px;font-size:12px;color:#71717a;white-space:nowrap;vertical-align:top;border-bottom:1px solid #f4f4f5">' + label + '</td>' +
    '<td style="padding:8px 14px;font-size:13px;color:#18181b;font-weight:bold;border-bottom:1px solid #f4f4f5">' + value + '</td>' +
  '</tr>';
}

function ctaButton() {
  return '' +
    '<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin:4px 0 6px"><tr><td>' +
      '<!--[if mso]><v:roundrect xmlns:v="urn:schemas-microsoft-com:vml" xmlns:w="urn:schemas-microsoft-com:office:word" href="' + HRIS_LINK + '" style="height:48px;v-text-anchor:middle;width:300px;" arcsize="21%" strokecolor="#ea580c" fillcolor="#ea580c"><w:anchorlock/><center style="color:#ffffff;font-family:Arial,sans-serif;font-size:15px;font-weight:bold;">Open HRIS &rarr; Accounting &rarr; Documents</center></v:roundrect><![endif]-->' +
      '<!--[if !mso]><!-- --><a href="' + HRIS_LINK + '" style="display:inline-block;background:#ea580c;color:#ffffff;font-size:15px;font-weight:bold;text-decoration:none;padding:14px 28px;border-radius:10px">Open HRIS &rarr; Accounting &rarr; Documents</a><!--<![endif]-->' +
    '</td></tr></table>';
}

function renderHtml() {
  const details =
    detailRow('Requested by', name + (workEmail ? ' &middot; <span style="font-weight:normal;color:#52525b">' + workEmail + '</span>' : '')) +
    detailRow('Document', 'Certificate of Engagement') +
    detailRow('Requested on', when ? when + ' <span style="font-weight:normal;color:#71717a">(Manila)</span>' : '') +
    detailRow('Their note', note) +
    detailRow('Reference ID', refId ? '<span style="font-family:Consolas,Menlo,monospace;font-weight:normal">' + refId + '</span>' : '');
  const testBanner = isTest
    ? '<tr><td style="background:#fef3c7;border-bottom:1px solid #fde68a;padding:10px 26px;font-size:12px;color:#92400e;font-weight:bold">TEST RUN &mdash; sent from Admin &rarr; Webhooks to you only. No employee filed this request.</td></tr>'
    : '';
  return '' +
    '<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>COE request</title></head>' +
    '<body style="margin:0;background:#f4f4f5;padding:24px 12px;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#18181b">' +
      '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:transparent;font-size:1px;line-height:1px">' + name + ' requested a Certificate of Engagement &mdash; it is waiting in Accounting &rarr; Documents.</div>' +
      '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5"><tr><td align="center">' +
        '<table role="presentation" width="520" cellpadding="0" cellspacing="0" style="width:100%;max-width:520px;background:#ffffff;border:1px solid #e4e4e7;border-radius:14px;overflow:hidden;box-shadow:0 6px 24px rgba(234,88,12,0.10)">' +
          testBanner +
          '<tr><td style="padding:18px 26px 12px"><img src="' + LOGO + '" alt="Simple" width="88" height="30" style="display:block;border:0;height:30px;width:88px"></td></tr>' +
          '<tr><td bgcolor="#0a0a0b" style="background:#0a0a0b;padding:22px 26px;border-bottom:4px solid #ea580c">' +
            '<span style="display:inline-block;background:#ea580c;color:#ffffff;font-size:11px;font-weight:bold;letter-spacing:1.5px;text-transform:uppercase;padding:5px 12px;border-radius:999px">&#128196; COE request</span>' +
            '<div style="margin-top:14px;font-size:22px;line-height:1.3;color:#ffffff;font-weight:bold">A Certificate of Engagement is waiting</div>' +
            '<div style="margin-top:6px;font-size:13px;color:#d4d4d8">An employee just requested one from their profile.</div>' +
          '</td></tr>' +
          '<tr><td style="padding:22px 26px 4px">' +
            '<p style="margin:0 0 14px;font-size:15px;color:#18181b">Hi,</p>' +
            '<p style="margin:0 0 16px;font-size:14px;line-height:1.6;color:#3f3f46">A <strong>Certificate of Engagement</strong> request was just filed in the HRIS. The certificate is already generated &mdash; it needs a review and a signature in <strong>Accounting &rarr; Documents</strong>.</p>' +
            '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#fff7ed;border:1px solid #fed7aa;border-radius:10px;margin:0 0 18px;overflow:hidden">' + details + '</table>' +
            ctaButton() +
            '<p style="margin:10px 0 18px;font-size:12px;color:#71717a;word-break:break-all">Button not working? Copy and paste this link:<br><a href="' + HRIS_LINK + '" style="color:#ea580c">' + esc(HRIS_LINK) + '</a></p>' +
          '</td></tr>' +
          '<tr><td style="padding:16px 26px 20px;border-top:1px solid #f4f4f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="font-size:12px;color:#52525b;font-weight:bold">Simple &middot; Confidential</td><td align="right" style="font-size:11px;color:#71717a">Automated alert from Simple HRIS</td></tr></table></td></tr>' +
        '</table>' +
        '<div style="max-width:520px;margin:12px auto 0;font-size:11px;color:#71717a;text-align:center;line-height:1.5">You are receiving this because you are on the COE request list in Admin &rarr; Webhooks.</div>' +
      '</td></tr></table>' +
    '</body></html>';
}

const html = renderHtml();
return recipients.map(function (email) {
  return { json: { to: email, subject: SUBJECT, html: html } };
});
